begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('f3f10000-0000-4000-8000-000000000001','tracking-a@example.test'),('f3f10000-0000-4000-8000-000000000002','tracking-b@example.test');
create function pg_temp.track(a jsonb,r bigint default null,c uuid default gen_random_uuid()) returns jsonb language sql as $$
 select public.apply_project_tracking_command(current_setting('test.project')::uuid,c,
   coalesce(r,(select revision from public.projects where id=current_setting('test.project')::uuid)),a)
$$;
select ok(not has_function_privilege('anon','public.apply_project_tracking_command(uuid,uuid,bigint,jsonb)','execute'),'anonymous cannot execute tracking RPC');
select ok(not has_function_privilege('service_role','public.apply_project_tracking_command(uuid,uuid,bigint,jsonb)','execute'),'service role not a public command path');
select ok(not has_table_privilege('authenticated','public.projects','UPDATE'),'projects remain RPC write only');
select ok(not has_table_privilege('authenticated','public.project_parts','UPDATE'),'parts remain RPC write only');
select ok(not has_table_privilege('authenticated','public.project_part_commands','SELECT'),'receipt history not directly exposed');
select ok((select relrowsecurity from pg_class where oid='public.projects'::regclass),'project RLS retained');
select ok((select relrowsecurity from pg_class where oid='public.project_parts'::regclass),'part RLS retained');
set local role authenticated;
set local request.jwt.claim.sub='f3f10000-0000-4000-8000-000000000001';
select set_config('test.created',public.create_project(gen_random_uuid(),'진행률 검증',null)::text,true);
select set_config('test.project',current_setting('test.created')::jsonb->>'id',true);
select set_config('test.part',current_setting('test.created')::jsonb->>'defaultPartId',true);
select set_config('test.work',current_setting('test.created')::jsonb->>'workItemId',true);
select is(current_setting('test.created')::jsonb->'progressPercent','null'::jsonb,'creation defaults to unset, not zero');
select is(public.get_project_detail(current_setting('test.project')::uuid)->'parts'->0->>'status','not_started','default part starts not_started');
select is(pg_temp.track('{"type":"setProgress","value":null}')->>'status','unchanged','unset no-op is receipted without revision bump');
select set_config('test.request',gen_random_uuid()::text,true);
select set_config('test.receipt',pg_temp.track('{"type":"setProgress","value":0}',0,current_setting('test.request')::uuid)::text,true);
select is(current_setting('test.receipt')::jsonb->'change'->'before','null'::jsonb,'receipt preserves previous null');
select is(current_setting('test.receipt')::jsonb->'change'->'after','0'::jsonb,'zero differs from unset');
select is(pg_temp.track('{"type":"setProgress","value":0}',0,current_setting('test.request')::uuid),jsonb_set(current_setting('test.receipt')::jsonb,'{status}','"duplicate"'),'exact lost-response retry returns original result');
select throws_ok(format('select pg_temp.track(''{"type":"setProgress","value":50}'',0,%L)',current_setting('test.request')),'22023',null,'changed request payload rejected');
select is(pg_temp.track('{"type":"setProgress","value":50}',0)->>'status','conflict','stale revision rejected');
select is(pg_temp.track('{"type":"setProgress","value":50}')->'change'->'after','50'::jsonb,'50 saved');
select is(pg_temp.track('{"type":"setProgress","value":100}')->'change'->'after','100'::jsonb,'100 saved');
select is((select status from public.projects where id=current_setting('test.project')::uuid),'active','100 does not complete project');
select is(public.get_project_detail(current_setting('test.project')::uuid)->'progressPercent','100'::jsonb,'detail exposes actual progress');
select is(pg_temp.track('{"type":"setProgress","value":null}')->'change'->'after','null'::jsonb,'progress can be reset to unset');
select is(public.update_project(current_setting('test.project')::uuid,4,'새 이름','메모','completed')->'progressPercent','null'::jsonb,'completed does not force 100');
select is(pg_temp.track('{"type":"setProgress","value":50}')->>'status','applied','completed project metadata remains editable');
select is(pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.part'),'status','in_progress'))->>'status','applied','default part editable even on completed project');
select is(public.apply_counter_command(gen_random_uuid(),current_setting('test.work')::uuid,0,now(),'tracking','{"type":"change","counter":"stitch","delta":1}')->>'status','rejected','completed project counting still blocked');
select public.update_project(current_setting('test.project')::uuid,7,'새 이름','메모','paused');
select is(pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.part'),'status','paused'))->>'status','applied','paused project part metadata editable');
select is((select status from public.projects where id=current_setting('test.project')::uuid),'paused','part status does not change project status');
select is(public.apply_counter_command(gen_random_uuid(),current_setting('test.work')::uuid,0,now(),'tracking','{"type":"change","counter":"stitch","delta":1}')->>'status','rejected','paused project counting still blocked');
select public.update_project(current_setting('test.project')::uuid,9,'새 이름','메모','active');
select is(public.apply_counter_command(gen_random_uuid(),current_setting('test.work')::uuid,0,now(),'tracking','{"type":"change","counter":"stitch","delta":1}')->>'status','applied','part paused does not impose a new counting policy');
select is(public.apply_counter_command(gen_random_uuid(),current_setting('test.work')::uuid,1,now(),'tracking','{"type":"setTarget","counter":"stitch","value":42}')->>'status','applied','target saved');
select set_config('test.session',gen_random_uuid()::text,true);
select is(public.apply_work_session_command(gen_random_uuid(),current_setting('test.session')::uuid,current_setting('test.work')::uuid,0,date_trunc('milliseconds',now()),'tracking','start')->>'status','applied','timer may run independent of part metadata');
select set_config('test.counter_snapshot',(select jsonb_agg(to_jsonb(c) order by id)::text from public.counters c where work_item_id=current_setting('test.work')::uuid),true);
select set_config('test.events_snapshot',(select jsonb_agg(to_jsonb(c) order by id)::text from public.counter_events c where work_item_id=current_setting('test.work')::uuid),true);
select set_config('test.timer_snapshot',(public.get_work_session(current_setting('test.session')::uuid)-'serverNow')::text,true);
select is(pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.part'),'status','completed'))->>'status','applied','part status allowed with active timer');
select is((select jsonb_agg(to_jsonb(c) order by id)::text from public.counters c where work_item_id=current_setting('test.work')::uuid),current_setting('test.counter_snapshot'),'counter IDs values and targets unchanged');
select is((select jsonb_agg(to_jsonb(c) order by id)::text from public.counter_events c where work_item_id=current_setting('test.work')::uuid),current_setting('test.events_snapshot'),'counter events unchanged and progress not an undo event');
select is((public.get_work_session(current_setting('test.session')::uuid)-'serverNow')::text,current_setting('test.timer_snapshot'),'session and timer events unchanged');
select is(pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.part'),'status','not_started'))->>'status','applied','all four manual part statuses supported');
select public.apply_work_session_command(gen_random_uuid(),current_setting('test.session')::uuid,current_setting('test.work')::uuid,1,date_trunc('milliseconds',now()),'tracking','end');
select set_config('test.second',public.apply_project_part_command(current_setting('test.project')::uuid,gen_random_uuid(),12,'{"type":"create","name":"소매"}')::text,true);
select is((select status from public.project_parts where id=(current_setting('test.second')::jsonb->>'partId')::uuid),'not_started','additional parts use same default');
select set_config('test.status_request',gen_random_uuid()::text,true);
select set_config('test.status_receipt',pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.second')::jsonb->>'partId','status','completed'),13,current_setting('test.status_request')::uuid)::text,true);
select is(pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.second')::jsonb->>'partId','status','completed'),13,current_setting('test.status_request')::uuid)->>'status','duplicate','part status retry is idempotent');
select is(pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.part'),'status','paused'),13)->>'status','conflict','part status uses shared project revision');
select public.apply_project_part_command(current_setting('test.project')::uuid,gen_random_uuid(),14,jsonb_build_object('type','rename','partId',current_setting('test.second')::jsonb->>'partId','name','긴 소매'));
select public.apply_project_part_command(current_setting('test.project')::uuid,gen_random_uuid(),15,jsonb_build_object('type','move','partId',current_setting('test.second')::jsonb->>'partId','direction','up'));
select is((select status from public.project_parts where id=(current_setting('test.second')::jsonb->>'partId')::uuid),'completed','rename and reorder preserve status');
select throws_ok(format('select public.apply_project_part_command(%L,gen_random_uuid(),16,%L)',current_setting('test.project'),jsonb_build_object('type','delete','partId',current_setting('test.part'))),'22023',null,'default part deletion restriction unchanged');
select public.apply_project_part_command(current_setting('test.project')::uuid,gen_random_uuid(),16,jsonb_build_object('type','delete','partId',current_setting('test.second')::jsonb->>'partId'));
select throws_ok(format('select pg_temp.track(%L)',jsonb_build_object('type','setPartStatus','partId',current_setting('test.second')::jsonb->>'partId','status','paused')),'P0002',null,'deleted part status edits blocked');
select public.delete_project(current_setting('test.project')::uuid,17);
select throws_ok(format('select public.apply_project_tracking_command(%L,gen_random_uuid(),18,''{"type":"setProgress","value":0}'')',current_setting('test.project')),'P0002',null,'deleted project edits blocked');
select public.restore_project(current_setting('test.project')::uuid,gen_random_uuid(),18);
select is((select progress_percent from public.projects where id=current_setting('test.project')::uuid),50,'restore retains progress');
select is((select count(*) from public.project_parts where project_id=current_setting('test.project')::uuid),1::bigint,'project restore does not restore individually deleted part');
select public.restore_project_part(current_setting('test.project')::uuid,(current_setting('test.second')::jsonb->>'partId')::uuid,gen_random_uuid(),19);
select is((select status from public.project_parts where id=(current_setting('test.second')::jsonb->>'partId')::uuid),'completed','part restore retains status');
select is((select work_item_id::text from public.project_parts where id=current_setting('test.part')::uuid),current_setting('test.work'),'original work item retained');
select is(pg_temp.track('{"type":"setProgress","value":50}')->>'status','unchanged','same progress does not advance revision');
select is(pg_temp.track(jsonb_build_object('type','setPartStatus','partId',current_setting('test.second')::jsonb->>'partId','status','completed'))->>'status','unchanged','same part status does not advance revision');
select is(pg_temp.track('{"type":"setProgress","value":0}',0,current_setting('test.request')::uuid)->'change'->'after','0'::jsonb,'old retry returns historical receipt after newer edits and restore');
select is((select revision from public.projects where id=current_setting('test.project')::uuid),20::bigint,'historical retry does not change latest revision');
select is((select progress_percent from public.projects where id=current_setting('test.project')::uuid),50,'historical retry does not overwrite latest progress');
-- Ownership and JSON shape tests below run with current revision to isolate input errors.
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": -1}')$q$,'22023',null,'invalid progress -1 rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": 101}')$q$,'22023',null,'invalid progress 101 rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": 50.5}')$q$,'22023',null,'invalid progress 50.5 rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": "50"}')$q$,'22023',null,'invalid progress "50" rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": true}')$q$,'22023',null,'invalid progress true rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": {}}')$q$,'22023',null,'invalid progress {} rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": []}')$q$,'22023',null,'invalid progress [] rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress"}')$q$,'22023',null,'malformed tracking action rejected');
select throws_ok($q$select pg_temp.track('{"type": "setProgress", "value": null, "extra": 1}')$q$,'22023',null,'malformed tracking action rejected');
select throws_ok($q$select pg_temp.track('{"type": "setPartStatus", "status": "active"}')$q$,'22023',null,'malformed tracking action rejected');
select throws_ok($q$select pg_temp.track('{"type": "setPartStatus", "partId": "bad", "status": "completed"}')$q$,'22023',null,'malformed tracking action rejected');
select throws_ok($q$select pg_temp.track('{"type": "setPartStatus", "partId": "f3f10000-0000-4000-8000-000000000001", "status": null}')$q$,'22023',null,'malformed tracking action rejected');

select set_config('test.other_project',public.create_project(gen_random_uuid(),'다른 프로젝트',null)::text,true);
select throws_ok(format('select pg_temp.track(%L)',jsonb_build_object('type','setPartStatus','partId',current_setting('test.other_project')::jsonb->>'defaultPartId','status','completed')),'P0002',null,'part from another project cannot be changed');
select throws_ok(format('select public.apply_project_part_command(%L,%L,0,''{"type":"create","name":"충돌"}'')',current_setting('test.project'),current_setting('test.request')),'22023',null,'legacy part command shares request ID namespace');
set local request.jwt.claim.sub='f3f10000-0000-4000-8000-000000000002';
select is((select count(*) from public.projects),0::bigint,'project RLS isolates other user');
select is((select count(*) from public.project_parts),0::bigint,'part RLS isolates other user');
select is(public.get_project_detail(current_setting('test.project')::uuid),null::jsonb,'detail does not expose other owner fields');
select throws_ok(format('select public.apply_project_tracking_command(%L,gen_random_uuid(),20,''{"type":"setProgress","value":0}'')',current_setting('test.project')),'P0002',null,'other user progress modification rejected');
select throws_ok(format('select public.apply_project_tracking_command(%L,gen_random_uuid(),20,%L)',current_setting('test.project'),jsonb_build_object('type','setPartStatus','partId',current_setting('test.part'),'status','paused')),'P0002',null,'other user part status rejected');
select set_config('test.second_owner',public.create_project(gen_random_uuid(),'다른 계정',null)->>'id',true);
select is(public.apply_project_tracking_command(current_setting('test.second_owner')::uuid,current_setting('test.request')::uuid,0,'{"type":"setProgress","value":50}')->>'status','applied','same request ID belongs to independent user namespace');
set local request.jwt.claim.sub='';
select throws_ok(format('select public.apply_project_tracking_command(%L,gen_random_uuid(),20,''{"type":"setProgress","value":0}'')',current_setting('test.project')),'28000',null,'missing auth rejected inside RPC');
reset role;
select throws_ok(format('update public.projects set progress_percent=-1 where id=%L',current_setting('test.project')),'23514',null,'DB range check rejects negative');
select throws_ok(format('update public.projects set progress_percent=101 where id=%L',current_setting('test.project')),'23514',null,'DB range check rejects over 100');
select throws_ok(format('update public.project_parts set status=''active'' where id=%L',current_setting('test.part')),'23514',null,'DB part enum check rejects unsupported values');
select throws_ok(format('update public.project_parts set status=null where id=%L',current_setting('test.part')),'23502',null,'DB part status not nullable');
select * from finish();
rollback;
